{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.snitchx_daily_summary AS ( WITH creator_users AS ( SELECT DISTINCT shopify_user_id FROM snitch_db.maplemonk.s3_bucket_wallet_transaction_db WHERE LOWER(reason) LIKE \'%creator%\' ), SnitchX_Members AS ( SELECT TRIM(shopify_user_id) AS shopify_user_id, CONVERT_TIMEZONE( \'UTC\',\'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP( CONCAT(membership_enrolled_date,\':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(membership_enrolled_date) END ) AS snitchx_ts FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ), post_online AS ( SELECT DATE_TRUNC(day, order_timestamp) AS order_date, order_timestamp AS order_ts, \'Online\' AS channel, REPLACE(order_name,\'#\',\'\') AS order_id, TRIM(customer_id) AS shopify_user_id, SUM(gross_sales) AS gross_sales, SUM(discount) - SUM(slashed_discount) AS discounts, SUM(CASE WHEN IS_REFUND = 0 THEN gross_sales ELSE 0 END) AS net_sales, SUM(quantity) AS qty FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH fi JOIN SnitchX_Members sm ON fi.customer_id = sm.shopify_user_id WHERE order_timestamp > sm.snitchx_ts AND LOWER(order_status) NOT LIKE \'%cancel%\' AND gross_sales <> 0 AND LOWER(tags) NOT LIKE \'%creator%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' AND customer_id NOT IN (SELECT shopify_user_id FROM creator_users) GROUP BY order_date, order_ts, order_name, customer_id ), post_offline AS ( SELECT DATE_TRUNC(day, vouch_ts) AS order_date, vouch_ts AS order_ts, \'Offline\' AS channel, bill_no AS order_id, TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) AS shopify_user_id, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.]\',\'\')) AS gross_sales, TRY_TO_NUMBER(REGEXP_REPLACE(discount ,\'[^0-9.]\',\'\')) AS discounts, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.]\',\'\')) AS net_sales, NULL AS qty FROM ( SELECT ros.*, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN IFF(ros.vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(ros.transaction_date, \'MON DD, YYYY, HH12:MI AM\') END AS vouch_ts FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros WHERE TRY_TO_NUMBER(REGEXP_REPLACE(TRIM(ros.bill_value),\'[^0-9.]\',\'\')) > 0 ) ros JOIN SnitchX_Members sm ON TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) = sm.shopify_user_id WHERE vouch_ts > sm.snitchx_ts AND ros.shopify_user_id NOT IN (SELECT shopify_user_id FROM creator_users) ), pre_last_online AS ( WITH latest_order AS ( SELECT customer_id, REPLACE(order_name,\'#\',\'\') AS order_id, order_timestamp, ROW_NUMBER() OVER ( PARTITION BY customer_id ORDER BY order_timestamp DESC) AS rn FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH fi JOIN SnitchX_Members sm ON fi.customer_id = sm.shopify_user_id WHERE fi.gross_sales > 0 AND order_timestamp <= sm.snitchx_ts AND DATEDIFF(day, order_timestamp, sm.snitchx_ts) < 4 AND LOWER(order_status) NOT LIKE \'%cancel%\' AND customer_id NOT IN (SELECT shopify_user_id FROM creator_users) ) , last_per_user AS ( SELECT customer_id, order_id FROM latest_order WHERE rn = 1 ) SELECT DATE_TRUNC(day, fi.order_timestamp) AS order_date, fi.order_timestamp AS order_ts, \'Online\' AS channel, REPLACE(fi.order_name,\'#\',\'\') AS order_id, TRIM(fi.customer_id) AS shopify_user_id, SUM(fi.gross_sales) AS gross_sales, SUM(fi.discount) - SUM(fi.slashed_discount) AS discounts, SUM(CASE WHEN fi.IS_REFUND = 0 THEN fi.gross_sales ELSE 0 END) AS net_sales, SUM(fi.quantity) AS qty FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH fi JOIN last_per_user lu ON fi.customer_id = lu.customer_id AND REPLACE(fi.order_name,\'#\',\'\') = lu.order_id GROUP BY order_date, fi.order_timestamp, fi.order_name, fi.customer_id ), pre_last_offline AS ( WITH ranked AS ( SELECT DATE_TRUNC(day, vouch_ts) AS order_date, vouch_ts AS order_ts, \'Offline\' AS channel, bill_no AS order_id, TRIM(REGEXP_REPLACE(shopify_user_id, \',\', \'\')) AS shopify_user_id, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\')) AS gross_sales, TRY_TO_NUMBER(REGEXP_REPLACE(discount,\'[^0-9.-]\',\'\')) AS discounts, TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\')) AS net_sales, NULL AS qty, ROW_NUMBER() OVER ( PARTITION BY TRIM(REGEXP_REPLACE(shopify_user_id, \',\', \'\')) ORDER BY vouch_ts DESC) AS rn FROM ( SELECT ros.*, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN IFF(ros.vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(ros.transaction_date,\'MON DD, YYYY, HH12:MI AM\') END AS vouch_ts FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary ros JOIN SnitchX_Members sm ON TRIM(REGEXP_REPLACE(ros.shopify_user_id, \',\', \'\')) = sm.shopify_user_id WHERE CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN IFF(ros.vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(ros.transaction_date,\'MON DD, YYYY, HH12:MI AM\') END <= sm.snitchx_ts AND DATEDIFF( day, CASE WHEN ros.vouch_time IS NOT NULL AND TRIM(ros.vouch_time) <> \'\' THEN IFF(ros.vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(ros.vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(ros.transaction_date,\'MON DD, YYYY, HH12:MI AM\') END, sm.snitchx_ts) < 4 AND ros.shopify_user_id NOT IN (SELECT shopify_user_id FROM creator_users) ) ) SELECT order_date, order_ts, channel, order_id, shopify_user_id, gross_sales, discounts, net_sales, qty FROM ranked WHERE rn = 1 ), combined_orders AS ( SELECT * FROM post_online UNION ALL SELECT * FROM post_offline UNION ALL SELECT * FROM pre_last_online UNION ALL SELECT * FROM pre_last_offline ), base_day_totals AS ( SELECT CAST(order_timestamp AS DATE) AS order_date, COUNT(DISTINCT REPLACE(order_name,\'#\',\'\')) AS total_orders, COUNT(DISTINCT customer_id) AS total_users, SUM(gross_sales) AS total_revenue FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' GROUP BY order_date UNION ALL SELECT CAST( CASE WHEN vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN IFF(vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(transaction_date,\'MON DD, YYYY, HH12:MI AM\') END AS DATE) AS order_date, COUNT(DISTINCT bill_no) AS total_orders, COUNT(DISTINCT TRIM(REGEXP_REPLACE(shopify_user_id,\',\',\'\'))) AS total_users, SUM(TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\'))) AS total_revenue FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary GROUP BY order_date ), base_day_totals_collapsed AS ( SELECT order_date, SUM(total_orders) AS total_orders, SUM(total_users) AS total_users, SUM(total_revenue) AS total_revenue FROM base_day_totals GROUP BY order_date ), base_day_totals_by_channel AS ( SELECT order_date, SUM(CASE WHEN channel = \'Online\' THEN total_orders END) AS total_online_orders, SUM(CASE WHEN channel = \'Offline\' THEN total_orders END) AS total_offline_orders, SUM(CASE WHEN channel = \'Online\' THEN total_users END) AS total_online_users, SUM(CASE WHEN channel = \'Offline\' THEN total_users END) AS total_offline_users, SUM(CASE WHEN channel = \'Online\' THEN total_revenue END) AS total_online_revenue, SUM(CASE WHEN channel = \'Offline\' THEN total_revenue END) AS total_offline_revenue FROM ( SELECT CAST(order_timestamp AS DATE) AS order_date, \'Online\' AS channel, COUNT(DISTINCT REPLACE(order_name,\'#\',\'\')) AS total_orders, COUNT(DISTINCT customer_id) AS total_users, SUM(gross_sales) AS total_revenue FROM snitch_db.maplemonk.FACT_ITEMS_SNITCH WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' GROUP BY order_date UNION ALL SELECT CAST( CASE WHEN vouch_time IS NOT NULL AND TRIM(vouch_time) <> \'\' THEN IFF(vouch_time ILIKE \'%12:% PM%\', TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH12:MI PM\'), TRY_TO_TIMESTAMP(vouch_time,\'MON DD, YYYY, HH:MI AM\')) ELSE TRY_TO_TIMESTAMP(transaction_date,\'MON DD, YYYY, HH12:MI AM\') END AS DATE) AS order_date, \'Offline\' AS channel, COUNT(DISTINCT bill_no) AS total_orders, COUNT(DISTINCT TRIM(REGEXP_REPLACE(shopify_user_id,\',\',\'\'))) AS total_users, SUM(TRY_TO_NUMBER(REGEXP_REPLACE(bill_value,\'[^0-9.-]\',\'\'))) AS total_revenue FROM snitch_db.maplemonk.retail_orders_summary_Retail_order_summary GROUP BY order_date ) GROUP BY order_date ) SELECT co.order_date, co.order_ts, s.snitchx_ts, co.channel, co.order_id, co.shopify_user_id, co.gross_sales, co.discounts, co.net_sales, co.qty, bdt.total_orders, bdt.total_users, bdt.total_revenue, bdc.total_online_orders, bdc.total_offline_orders, bdc.total_online_users, bdc.total_offline_users, bdc.total_online_revenue, bdc.total_offline_revenue FROM combined_orders co LEFT JOIN SnitchX_Members s ON co.shopify_user_id = s.shopify_user_id LEFT JOIN base_day_totals_collapsed bdt ON co.order_date = bdt.order_date LEFT JOIN base_day_totals_by_channel bdc ON co.order_date = bdc.order_date ORDER BY co.order_date, co.order_id ) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            